399		}
400		if recs[1].Decision.Request.Subject.ID != "u1" || recs[1].Decision.Request.Action != "read" {
401			t.Fatalf("stored request mutated by caller: %+v", recs[1].Decision.Request)
402		}
403	
404		// Mutating query/export results must not change stored records.
405		recs[0].Change.Policies[0].Subject = "hacker"
406		recs[1].Decision.Request.Subject.ID = "hacker"
407		again, _, err := s.AuditExport("acme", 0)
408		if err != nil {
409			t.Fatal(err)
410		}
411		if again[0].Change.Policies[0].Subject != "u1" || again[1].Decision.Request.Subject.ID != "u1" {
412			t.Fatal("stored records changed via exported copies")
413		}
414		page, err := s.AuditQuery("acme", 1, 10, "", "")
415		if err != nil {
416			t.Fatal(err)
417		}
418		page.Records[0].Change.Policies[0].ID = "rewritten"
419		onceMore, _, _ := s.AuditExport("acme", 0)
420		if onceMore[0].Change.Policies[0].ID != "p1" {
421			t.Fatal("stored records changed via query copies")
422		}
423	}
