import re
p = 'darksafe/audit.go'
src = open(p).read()
# Inject a pre-verification terminal short-circuit right after pageSize/nextSeq arg checks,
# i.e. before taking the lock/verifying the checkpoint.
needle = """	if nextSeq < 0 {
		return nil, fmt.Errorf("%w: next sequence must be >= 0, got %d", ErrInvalidPage, nextSeq)
	}
	s.mu.Lock()"""
assert needle in src
mutant = """	if nextSeq < 0 {
		return nil, fmt.Errorf("%w: next sequence must be >= 0, got %d", ErrInvalidPage, nextSeq)
	}
	if nextSeq == 0 {
		// MUTANT: trust the checkpoint at the terminal cursor.
		return &AuditPage{Org: cp.Org, BeginSeq: 1, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
	}
	s.mu.Lock()"""
open(p,'w').write(src.replace(needle, mutant))
EOF
